    directpay_description: 'Envía y recibe pagos directamente entre dos billeteras mediante una conexión cifrada entre pares. El pago normalmente va directamente de una billetera a otra; el buzón de mensajes o el servidor de retransmisión solo transmite los datos de conexión cifrados, y el buzón de mensajes los guarda solo hasta que se leen. Si las billeteras no pueden conectarse directamente, un servidor TURN puede retransmitir la conexión cifrada. El buzón de mensajes, el servidor de retransmisión y el servidor TURN pueden ver qué billeteras se conectan, sus direcciones IP y cuándo, pero nunca el pago; los servidores STUN ven la dirección IP de este dispositivo cuando se conecta. Enviar directamente no requiere configuración; recibir está activado salvo que lo desactives.',
