    directpay_title: 'Paiements directs',
    directpay_description: 'Envoyez et recevez des paiements directement entre deux portefeuilles via une connexion pair à pair chiffrée. Le paiement passe généralement directement d\'un portefeuille à l\'autre ; la boîte aux lettres ou le serveur relais ne transmet que les informations de connexion chiffrées, et la boîte aux lettres ne les conserve que jusqu\'à leur lecture. Si les portefeuilles ne peuvent pas se connecter directement, un serveur TURN peut relayer la connexion chiffrée. La boîte aux lettres, le serveur relais et le serveur TURN peuvent voir quels portefeuilles se connectent, leurs adresses IP et à quel moment, mais jamais le paiement ; les serveurs STUN voient l\'adresse IP de cet appareil lorsqu\'il se connecte. L\'envoi direct ne demande aucune configuration ; la réception est activée sauf si vous la désactivez.',
