    directpay_title: 'Pagamentos diretos',
    directpay_description: 'Envie e receba pagamentos diretamente entre duas carteiras por uma conexão ponto a ponto criptografada. O pagamento normalmente vai diretamente de uma carteira para a outra; a caixa de mensagens ou o servidor de retransmissão apenas transmite os dados de conexão criptografados, e a caixa de mensagens os guarda somente até serem lidos. Se as carteiras não conseguirem se conectar diretamente, um servidor TURN pode retransmitir a conexão criptografada. A caixa de mensagens, o servidor de retransmissão e o servidor TURN podem ver quais carteiras se conectam, seus endereços IP e quando, mas nunca o pagamento; os servidores STUN veem o endereço IP deste dispositivo quando ele se conecta. Enviar diretamente não exige configuração; o recebimento fica ativado, a menos que você o desative.',
