    directpay_description: 'एन्क्रिप्टेड पीयर-टू-पीयर कनेक्शन के ज़रिए दो वॉलेट के बीच सीधे भुगतान भेजें और प्राप्त करें। भुगतान आमतौर पर सीधे दोनों वॉलेट के बीच जाता है; मैसेज बॉक्स या रिले सर्वर केवल एन्क्रिप्टेड कनेक्शन विवरण आगे भेजता है, और मैसेज बॉक्स उन्हें केवल तब तक रखता है जब तक वे पढ़े नहीं जाते। अगर वॉलेट सीधे कनेक्ट नहीं हो पाते, तो कोई TURN सर्वर एन्क्रिप्टेड कनेक्शन को रिले कर सकता है। मैसेज बॉक्स, रिले सर्वर और TURN सर्वर देख सकते हैं कि कौन-से वॉलेट कनेक्ट होते हैं, उनके IP पते और कब, लेकिन भुगतान कभी नहीं; STUN सर्वर कनेक्ट होते समय इस डिवाइस का IP पता देखते हैं। सीधे भेजने के लिए किसी सेटअप की ज़रूरत नहीं है; प्राप्त करना तब तक चालू रहता है जब तक आप इसे बंद नहीं करते।',
