    directpay_title: 'সরাসরি পেমেন্ট',
    directpay_description: 'এনক্রিপ্ট করা পিয়ার-টু-পিয়ার সংযোগের মাধ্যমে দুটি ওয়ালেটের মধ্যে সরাসরি পেমেন্ট পাঠান ও গ্রহণ করুন। পেমেন্ট সাধারণত সরাসরি দুটি ওয়ালেটের মধ্যে যায়; মেসেজ বক্স বা রিলে সার্ভার শুধু এনক্রিপ্ট করা সংযোগের তথ্য পৌঁছে দেয়, আর মেসেজ বক্স সেগুলো পড়া না হওয়া পর্যন্তই রাখে। ওয়ালেটগুলো সরাসরি সংযুক্ত হতে না পারলে একটি TURN সার্ভার এনক্রিপ্ট করা সংযোগটি রিলে করতে পারে। মেসেজ বক্স, রিলে সার্ভার ও TURN সার্ভার দেখতে পারে কোন ওয়ালেটগুলো সংযুক্ত হচ্ছে, তাদের IP ঠিকানা এবং কখন, কিন্তু পেমেন্ট কখনোই নয়; STUN সার্ভার এই ডিভাইস সংযুক্ত হওয়ার সময় এর IP ঠিকানা দেখে। সরাসরি পাঠাতে কোনো সেটআপ লাগে না; আপনি বন্ধ না করা পর্যন্ত গ্রহণ চালু থাকে।',
