    directpay_description: 'أرسل واستقبل المدفوعات مباشرة بين محفظتين عبر اتصال مشفّر من نظير إلى نظير. تنتقل الدفعة عادةً مباشرة بين المحفظتين؛ ولا ينقل صندوق الرسائل أو خادم الترحيل سوى بيانات الاتصال المشفّرة، ويحتفظ بها صندوق الرسائل فقط إلى أن تُقرأ. إذا تعذّر اتصال المحفظتين مباشرة، فقد يُرحِّل خادم TURN الاتصال المشفّر. يمكن لصندوق الرسائل وخادم الترحيل وخادم TURN معرفة المحافظ التي تتصل وعناوين IP الخاصة بها ووقت الاتصال، لكن ليس الدفعة أبدًا؛ وترى خوادم STUN عنوان IP لهذا الجهاز عند اتصاله. الإرسال المباشر لا يحتاج إلى إعداد؛ ويبقى الاستقبال مفعّلًا ما لم تقم بإيقافه.',
