    directpay_description: 'Отправляйте и получайте платежи напрямую между двумя кошельками через зашифрованное одноранговое соединение. Платёж обычно идёт напрямую между кошельками; ящик сообщений или сервер-ретранслятор лишь передаёт зашифрованные данные для соединения, а ящик сообщений хранит их только до прочтения. Если кошельки не могут соединиться напрямую, TURN-сервер может ретранслировать зашифрованное соединение. Ящик сообщений, сервер-ретранслятор и TURN-сервер видят, какие кошельки соединяются, их IP-адреса и время, но никогда не видят сам платёж; STUN-серверы видят IP-адрес этого устройства при подключении. Для прямой отправки настройка не нужна; получение включено, пока вы его не выключите.',
