    directpay_description: 'Wysyłaj i odbieraj płatności bezpośrednio między dwoma portfelami przez szyfrowane połączenie peer-to-peer. Płatność zwykle trafia bezpośrednio z portfela do portfela; skrzynka wiadomości lub serwer przekaźnikowy przekazuje tylko zaszyfrowane dane połączenia, a skrzynka wiadomości przechowuje je tylko do chwili ich odczytania. Jeśli portfele nie mogą połączyć się bezpośrednio, serwer TURN może przekazywać zaszyfrowane połączenie. Skrzynka wiadomości, serwer przekaźnikowy i serwer TURN widzą, które portfele się łączą, ich adresy IP i kiedy, ale nigdy samej płatności; serwery STUN widzą adres IP tego urządzenia, gdy się łączy. Wysyłanie bezpośrednie nie wymaga konfiguracji; odbieranie pozostaje włączone, dopóki go nie wyłączysz.',
